  ('a214a640-a700-4327-b643-36df835de680', 'f7d2b5e1-4c68-4a09-9b17-3e0d8c6a5f24', null, 'topic'::public.curated_course_node_type, 'Needs and Asset Assessment', 'This opening unit teaches students to define public health problems with rigor and humility. The goal is to combine epidemiologic evidence, community knowledge, service-system data, and asset mapping so program priorities respond to real needs rather than assumptions.', 0),
